package io.coolbox.ensemble;
import io.coolbox.internal.*;import com.sun.jna.ptr.DoubleByReference;
/** Regression ensemble (Python: {@code tree_ensemble.BoostTree}). */
public final class BoostTree extends NativeHandle {private static final EnsembleNative N=EnsembleNative.INSTANCE;private int features;public BoostTree(){this(new BoostTreeParameters());}public BoostTree(BoostTreeParameters p){super(create(p),N::coolbox_boost_tree_regressor_free);}private static com.sun.jna.Pointer create(BoostTreeParameters p){ErrorBuffer e=new ErrorBuffer();return e.check(N.coolbox_boost_tree_regressor_new(p.numEstimators,p.learningRate,p.maxDepth,e.pointer(),e.capacity()));}public BoostTree fit(double[][] x,double[] y){features=Matrices.columns(x);if(y.length!=x.length)throw new IllegalArgumentException("target count differs from rows");ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_regressor_fit(handle(),Matrices.flatten(x),x.length,features,y,e.pointer(),e.capacity()));return this;}public double predict(double[] sample){DoubleByReference o=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_regressor_predict(handle(),sample,sample.length,o,e.pointer(),e.capacity()));return o.getValue();}public double[] predictBatch(double[][] x){int c=Matrices.columns(x);double[] out=new double[x.length];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_regressor_predict_batch(handle(),Matrices.flatten(x),x.length,c,out,e.pointer(),e.capacity()));return out;}}
